message.content:
{
  "title": "The Glass Diver's Rescue",
  "gate_token": "Y7jLI72kx0J8_NGaLWpgtQ",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara the Cartographer studies a cracked map of the ruined city.",
      "visual_description": "Mara stands at the edge of a crumbled wall, holding a tattered map while the setting sun casts long shadows over broken spires.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The glass diver arrives through a shattered window.",
      "visual_description": "The glass diver emerges from a mirror-like portal, his helmet reflecting the orange sky and distant castle gates.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp flickers to life with a warning.",
      "visual_description": "Inside a ruined hall, the oracle lamp's single eye glows as it speaks, casting eerie shadows on the cracked walls.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "Mara and the glass diver discuss the route past the cursed towers.",
      "visual_description": "The two huddle over the map as the glass diver points toward a cluster of twisted black towers in the distance.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "They encounter the tin fox near the royal banner remains.",
      "visual_description": "A small metal fox with blue glass eyes stands beside a torn old banner, its tail ticking softly.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The tin fox leads them to a hidden entrance beneath the castle gates.",
      "visual_description": "The fox scratches at a rusted grate under the massive gates, while Mara and the glass diver follow cautiously.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "The oracle lamp warns of armored patrols.",
      "visual_description": "The lamp's eye narrows as it whispers, showing a vision of figures in plate armor marching through the streets.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "The glass diver uses a mirror to scout ahead unnoticed.",
      "visual_description": "The glass diver presses a hand to a cracked mirror, his reflection stepping through to peek around a corner.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "Mara finds a locked magic door on the map.",
      "visual_description": "Mara traces a glowing rune on the map, her compass spinning wildly before pointing to a door covered in shifting symbols.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "The sleeping tax collector blocks the magic door.",
      "visual_description": "Curled up against the door, the tax collector snores softly, stamps and papers fluttering with each breath.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "The glass diver coaxes a key from the sleeping tax collector.",
      "visual_description": "The glass diver gently lifts a brass key from under the tax collector's sleeve, careful not to wake him.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 12,
      "caption": "The magic door opens with a silent pulse.",
      "visual_description": "The door's symbols rearrange themselves and swing open into a dark corridor, revealing a staircase descending.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "Inside, they find rumors of dragons etched on the walls.",
      "visual_description": "The corridor walls are covered in ancient carvings of wing shapes and coiled bodies, the air smelling of ash.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "The oracle lamp flares to reveal a trap ahead.",
      "visual_description": "The lamp's flame turns blue, illuminating a pit lined with spikes that was hidden in the darkness.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "The tin fox disarms the trap with a tiny gear.",
      "visual_description": "The fox inserts a gear into a wall mechanism, causing the spikes to retract with a grinding sound.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 16,
      "caption": "They reach the bridge under a moonlit sky.",
      "visual_description": "A narrow stone bridge spans a chasm, the ruined city behind them and freedom ahead, moonlight glinting on the glass diver's helmet.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "Armored patrols appear on both ends of the bridge.",
      "visual_description": "Figures in full plate armor march onto the bridge from both sides, cutting off escape.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "The glass diver shatters a mirror to create a distraction and they escape.",
      "visual_description": "The glass diver throws a mirror shard, which explodes into blinding light; the group dashes across the bridge into the dark forest beyond.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

